var e={name:"mkcert",description:"A simple tool for making locally-trusted development certificates",args:{name:"host",description:"Hostnames, IPs, or URIs to include in the certificate",isVariadic:!0,isOptional:!0},options:[{name:"-install",description:"Install the local CA in the system trust store"},{name:"-uninstall",description:"Uninstall the local CA (but do not delete it)"},{name:"-cert-file",description:"Customize the output certificate path",args:{name:"file",template:"filepaths"}},{name:"-key-file",description:"Customize the output key path",args:{name:"file",template:"filepaths"}},{name:"-p12-file",description:"Customize the output PKCS #12 path",args:{name:"file",template:"filepaths"}},{name:"-client",description:"Generate a certificate for client authentication"},{name:"-ecdsa",description:"Generate a certificate with an ECDSA key"},{name:"-pkcs12",description:'Generate a ".p12" PKCS #12 file for legacy applications'},{name:"-csr",description:"Generate a certificate based on the supplied CSR",args:{name:"csr",template:"filepaths"}},{name:"-CAROOT",description:"Print the CA certificate and key storage location"},{name:"-help",description:"Print the help message"},{name:"-version",description:"Print the version"}]},t=e;export{t as default};
